    "content": "36氪获悉，11月3日，果实进化与蚂蚁数科在中国香港签署合作备忘录。根据备忘录，蚂蚁数科提供云计算、MaaS和Agent平台支撑，果实进化提供服务业模型能力与具身实景训练能力，双方将在中国香港落地合作，推进深化AI现场智能管理与具身产业化。"
