    "content": "新华社华盛顿11月3日电 美国总统特朗普3日在接受英国《金融时报》采访时表示，美国没有立即打击伊朗的计划，但随时“严阵以待”。 在这段时长6分钟的电话采访中，特朗普称，他对当前美伊局面“感到满意”，“我们似乎正在得到我们想要的一切”。 针对以色列总理内塔尼亚胡曾暗示或在本周晚些时候打击伊朗，特朗普回应称：“我准备好了，我们也准备好了。如果需要行动，我们随时严阵以待，但可能根本没必要这么做。”他说，不会事先透露任何打击计划。 特朗普在采访中表示，美国对伊朗港口的封锁已成功“扼杀”伊朗经济，“局面非常理想”。 他同时透…"
