    "description": "11月4日，国务院台办举行例行新闻发布会。有记者问，近期，大陆商用卫星“吉林一号”公布多张台湾高清卫星影像，引发两岸网友关注和热议。请问对此有何评论？ 发言人朱凤莲答问表示，这一组分辨率极高的卫星影像让两岸同胞清晰地看到了台湾的城市、田园、盐田、湿地和港湾，领略了祖国宝岛的山海风华，引发了两岸网友在社交平台热烈的互动。这既展现了大陆航天科技的发展进步，也充分展现两岸同胞现在可以享受到多元化的遥感信息服务，用科技的力量守护两岸的共同家园。…",
