    "content": "新华社伦敦11月3日电（记者高文成）总部位于英国的温沃德海事分析公司3日发布报告说，此前被报道装载俄罗斯柴油驶往美国的三艘油轮中，目前仅一艘仍似驶向美国东海岸，另外两艘在船舶自动识别系统中更新的目的地信息显示，其原定赴美计划可能已调整。 报告说，悬挂俄罗斯国旗的“TALISMAN”号已将该系统中自行申报的目的地由“大西洋沿岸，等待指令”改为“等待指令”，不再注明具体目的地区域。悬挂塞拉利昂国旗的“LERUO”号则将目的地由“大西洋沿岸，等待指令”改为“巴西，等待指令”，表明其航行计划可能转向巴西。 报告指出，这两艘…"
