    "title": "[问与答] 移动物理网卡与 CDN 的问题",
    "link": "https://www.v2ex.com/t/1254331#reply0",
    "pub_date": "2026-11-04 10:12:35",
    "author": "zzlyzq",
    "description": "移动物联网卡一般配置白名单，不超过 10 个 ip 地址。 如果业务域名涉及到物联网卡设备，那么使用 CDN 会有问题。毕竟绑定了白名单。 那么，是否可以获取移动物联网卡的 DNS 服务器（递归服务请求的 DNS 服务器）地址，这样可以尝试做一下 zone 解析，使得物联网卡直接解析出源站（绑定到了物联网白名单地址列表中）正常使用，其他流量来源解析到 CDN 服务器。",
    "content": "移动物联网卡一般配置白名单，不超过 10 个 ip 地址。 如果业务域名涉及到物联网卡设备，那么使用 CDN 会有问题。毕竟绑定了白名单。 那么，是否可以获取移动物联网卡的 DNS 服务器（递归服务请求的 DNS 服务器）地址，这样可以尝试做一下 zone 解析，使得物联网卡直接解析出源站（绑定到了物联网白名单地址列表中）正常使用，其他流量来源解析到 CDN 服务器。"
