    "content": "记者今天了解到，市场监管总局出台《市场监督管理行政处罚裁量规定》，以部门规章形式对规范市场监管行政处罚裁量权作出系统性规定。 《规定》在现行《关于规范市场监督管理行政处罚裁量权的指导意见》基础上，将裁量规则从规范性文件上升为部门规章，提升了制度的刚性和权威性。同时，《规定》明确了裁量基准的制定主体、制定程序、主要内容以及调整适用等要求，进一步提升裁量基准的科学性和精准性。 《规定》将行政处罚裁量划分为不予处罚、减轻处罚、从轻处罚、一般处罚、从重处罚五个阶次，并对各阶次的适用情形作出具体规定。 一方面，增加“违法行为…"
